css:
.d-le{box-sizing:border-box;width:260px;max-width:100%;height:150px;display:grid;place-items:center;perspective:640px}
.d-le-deck{position:relative;width:196px;height:84px;transform-style:preserve-3d;transform:rotateX(18deg) rotateY(-14deg)}
.d-le-plate{position:absolute;inset:0;box-sizing:border-box;display:flex;align-items:center;justify-content:space-between;padding:0 12px;border:1px solid var(--line);border-radius:6px;background:var(--paper);color:var(--ink);transform:translateZ(var(--z,0px));transition:transform 280ms cubic-bezier(.34,1.56,.64,1),opacity 180ms cubic-bezier(.34,1.56,.64,1),border-color 120ms cubic-bezier(.34,1.56,.64,1);will-change:transform}
.d-le-plate:nth-child(1){--z:0px;z-index:1}
.d-le-plate:nth-child(2){--z:26px;z-index:2}
.d-le-plate:nth-child(3){--z:52px;z-index:3}
.d-le-no{font-family:var(--font-mono);font-size:var(--fs-11);font-weight:400;letter-spacing:var(--tracking-mono-label);color:var(--faint)}
.d-le-name{font-size:var(--fs-13);font-weight:600}
.d-le-deck.is-hot .d-le-plate{opacity:.45;transform:translateZ(-18px)}
.d-le-deck.is-hot .d-le-plate.is-on{opacity:1;border-color:var(--ink);transform:translateZ(64px)}
.d-le-plate:focus-visible{outline:1px solid var(--ink);outline-offset:2px}

init:
root => {
  const deck = root.querySelector('.d-le-deck');
  if (!deck || deck.dataset.le) return;
  deck.dataset.le = '1';
  const plates = Array.from(deck.querySelectorAll('.d-le-plate'));
  const on = el => { deck.classList.add('is-hot'); plates.forEach(p => p.classList.toggle('is-on', p === el)); };
  const off = () => { deck.classList.remove('is-hot'); plates.forEach(p => p.classList.remove('is-on')); };
  deck.addEventListener('pointerover', e => { const p = e.target.closest('.d-le-plate'); if (p) on(p); });
  deck.addEventListener('pointerout', e => { const p = e.target.closest('.d-le-plate'); if (p && !p.contains(e.relatedTarget)) off(); });
  deck.addEventListener('focusin', e => { const p = e.target.closest('.d-le-plate'); if (p) on(p); });
  deck.addEventListener('focusout', e => { const p = e.target.closest('.d-le-plate'); if (p && !p.contains(e.relatedTarget)) off(); });
  deck.addEventListener('keydown', e => { if (e.key === 'Escape') off(); });
}
